package com.weeklyplan.partner;
import com.weeklyplan.user.AppUser; import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="partner_resource_follow_ups") public class PartnerResourceFollowUp { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="resource_id",nullable=false) private PartnerResource resource; @Column(columnDefinition="TEXT",nullable=false) private String content; @Column(name="follow_up_date",nullable=false) private LocalDate followUpDate; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="created_by_user_id",nullable=false) private AppUser createdBy; @Column(name="created_at",nullable=false) private Instant createdAt; public Long getId(){return id;} public PartnerResource getResource(){return resource;} public String getContent(){return content;} public LocalDate getFollowUpDate(){return followUpDate;} public AppUser getCreatedBy(){return createdBy;} public Instant getCreatedAt(){return createdAt;} public static PartnerResourceFollowUp create(PartnerResource p,AppUser u,SavePartnerFollowUpRequest r){PartnerResourceFollowUp f=new PartnerResourceFollowUp();f.resource=p;f.createdBy=u;f.content=r.content().trim();f.followUpDate=r.followUpDate();f.createdAt=Instant.now();return f;} }
